import json

before = json.load(open('/tmp/baseline-pkg-output.json'))
after = json.load(open('/tmp/after-cpm-output.json'))

def extract(data):
    pkgs = {}
    for proj in data.get('projects', []):
        name = proj['path'].split('/')[-1]
        for fw in proj.get('frameworks', []):
            tfm = fw['framework']
            for pkg in fw.get('topLevelPackages', []):
                key = (name, tfm, pkg['id'])
                pkgs[key] = pkg['resolvedVersion']
    return pkgs

b = extract(before)
a = extract(after)
all_keys = sorted(set(b.keys()) | set(a.keys()))

changes = []
unchanged = []
for k in all_keys:
    proj, tfm, pkg_id = k
    bv = b.get(k, '-')
    av = a.get(k, '-')
    if bv != av:
        changes.append((proj, tfm, pkg_id, bv, av))
    else:
        unchanged.append((proj, tfm, pkg_id, bv))

print('=== CHANGES ===')
if changes:
    for c in changes:
        print(f'{c[0]} ({c[1]}): {c[2]} {c[3]} -> {c[4]}')
else:
    print('None')

print()
print(f'=== UNCHANGED: {len(unchanged)} packages ===')
for u in unchanged:
    print(f'{u[0]} ({u[1]}): {u[2]} {u[3]}')
